local legacy = { [22652] = true, [22654] = true, [22655] = true, [22658] = true }
local seen = {}
for _, source in pairs(sources) do
  for itemid, entry in pairs(source.items or {}) do
    local extra = imported[itemid]
    if extra then
      for key, value in pairs(extra) do
        if key ~= "sourceGroup" and key ~= "expansionLevel" then entry[key] = value end
      end
      seen[itemid] = true
    end
    if legacy[itemid] then
      entry.recipeSource = "Legacy/retired recipe - check for an established crafter or server availability"
    end
  end
end
for itemid, entry in pairs(imported) do
  if not seen[itemid] then
    local key = entry.sourceGroup
    if not sources[key] then
      sources[key] = groups[key]
      sources[key].items = {}
    end
    sources[key].items[itemid] = entry
  end
end

